{"path": "wordy.py", "content": "import operator

OPERATIONS = {
    "plus": operator.add,
    "minus": operator.sub,
    "multiplied by": operator.mul,
    "divided by": lambda a, b: int(a / b),
}


def _to_int(token):
    try:
        return int(token)
    except (TypeError, ValueError):
        return None


def answer(question):
    prefix = "What is"
    if not question.startswith(prefix):
        raise ValueError("unknown operation")

    body = question[len(prefix):].strip().rstrip("?").strip()
    body = body.replace("multiplied by", "multiplied_by").replace("divided by", "divided_by")
    tokens = [token.replace("_", " ") for token in body.split()]

    if not tokens:
        raise ValueError("syntax error")

    result = _to_int(tokens[0])
    if result is None:
        if tokens[0] in OPERATIONS:
            raise ValueError("syntax error")
        raise ValueError("unknown operation")

    index = 1
    while index < len(tokens):
        op_token = tokens[index]
        if op_token not in OPERATIONS:
            if _to_int(op_token) is not None:
                raise ValueError("syntax error")
            raise ValueError("unknown operation")
        if index + 1 >= len(tokens):
            raise ValueError("syntax error")
        operand = _to_int(tokens[index + 1])
        if operand is None:
            if tokens[index + 1] in OPERATIONS:
                raise ValueError("syntax error")
            raise ValueError("unknown operation")
        result = OPERATIONS[op_token](result, operand)
        index += 2

    return result
"}

